		b.setBinding("k", factory.createLiteral("same"));
		b.setBinding("rep", factory.createLiteral("b"));
		var a = new org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet();
		a.setBinding("k", factory.createLiteral("same"));
		a.setBinding("rep", factory.createLiteral("a"));
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("k", "rep"));
		values.setBindingSets(List.of(b, a));
		return values;
