	private static QueryEvaluationStep recording(QueryEvaluationStep delegate, AtomicInteger closes,
			AtomicBoolean ownerFree, List<String> encounterOrder) {
		return bindings -> {
			CloseableIteration<BindingSet> rows = delegate.evaluate(bindings);
			ownerFree.set(NativeExecutionContextCarrier.contextOf(rows) == null);
			return new CloseableIteration<>() {
				private boolean closed;

				@Override
				public boolean hasNext() {
					return !closed && rows.hasNext();
				}

				@Override
				public BindingSet next() {
					BindingSet row = rows.next();
					if (row.hasBinding("rep")) {
						encounterOrder.add(row.getValue("rep").stringValue());
					}
					return row;
				}

				@Override
				public void remove() {
					throw new UnsupportedOperationException();
				}

				@Override
				public void close() {
					if (!closed) {
						closed = true;
						closes.incrementAndGet();
						rows.close();
					}
				}
			};
		};
	}

	private static List<String> representatives(List<BindingSet> rows) {
		return rows.stream().map(row -> row.getValue("rep").stringValue()).toList();
	}

	private static boolean hasInterruption(Throwable failure) {
		if (failure instanceof QueryInterruptedException) {
			return true;
		}
		return failure != null && hasInterruption(failure.getCause());
	}

	private static final class InterruptingKeyFunction implements Function {
		private final String uri = "urn:rdf4j:test:owner-free-order-interrupt:" + UUID.randomUUID();
		private final Determinism determinism;
		private final AtomicBoolean armed = new AtomicBoolean();
		private final AtomicBoolean callbackClaimed = new AtomicBoolean();
		private final AtomicBoolean interruptObserved = new AtomicBoolean();
		private final CountDownLatch comparisonEntered = new CountDownLatch(1);

		private InterruptingKeyFunction(Determinism determinism) {
			this.determinism = determinism;
		}

		@Override
		public String getURI() {
			return uri;
		}

		@Override
		public Determinism getDeterminism() {
			return determinism;
		}

		@Override
		public Value evaluate(ValueFactory factory, Value... arguments) {
			IRI value = factory.createIRI("urn:rdf4j:test:order-key:" + arguments[0].stringValue());
			return new IRI() {
				private static final long serialVersionUID = 1L;

				@Override
				public String getNamespace() {
					return value.getNamespace();
				}

				@Override
				public String getLocalName() {
					return value.getLocalName();
				}

				@Override
				public String stringValue() {
					return value.stringValue();
				}

				@Override
				public boolean equals(Object other) {
					return value.equals(other);
				}

				@Override
				public int hashCode() {
					return value.hashCode();
				}

				@Override
				public String toString() {
					if (armed.get() && callbackClaimed.compareAndSet(false, true)) {
						comparisonEntered.countDown();
						try {
							new CountDownLatch(1).await();
						} catch (InterruptedException interrupted) {
							Thread.currentThread().interrupt();
							interruptObserved.set(Thread.currentThread().isInterrupted());
							throw new QueryInterruptedException("owner-free ORDER comparison interrupted", interrupted);
						}
					}
					return value.toString();
				}
			};
		}

		private void arm() {
			armed.set(true);
		}
	}

